    private final Runnable refreshTimers=()->{int position=list.getFirstVisiblePosition();View child=list.getChildAt(0);int offset=child==null?0:child.getTop();render();list.setSelectionFromTop(position,offset);};
    @Override protected void onResume(){super.onResume();if(root!=null)refreshTimers.run();}
