    @Override protected void onDestroy(){refreshHandler.removeCallbacksAndMessages(null);super.onDestroy();}
    @Override public void onCreate(Bundle state){super.onCreate(state);
        try{planner=Store.planner(this);sample=getIntent().getBooleanExtra("sample",false);
            if(sample){raw=sampleExport();village=ExportParser.parse(raw,Store.catalog(this),System.currentTimeMillis());}
            else{village=Store.load(this,getIntent().getStringExtra("tag"));if(village==null){finish();return;}raw=Store.raw(this,village.tag);}
            if(state!=null){base=state.getString("base","home");tab=UpgradePlanner.Tab.values()[Math.max(0,Math.min(3,state.getInt("tab")))];
                JSONObject saved=new JSONObject(state.getString("filters","{}"));for(Iterator<String> keys=saved.keys();keys.hasNext();){String key=keys.next();filters.put(key,readFilter(saved.getJSONObject(key)));}}
            if(base.equals("builder")&&tab.ordinal()>1)tab=UpgradePlanner.Tab.BUILDINGS;shell();render();
        }catch(Exception error){TextView message=label("Could not load upgrade data. Import a fresh export and try again.",18,WHITE,true);message.setPadding(dp(24),dp(40),dp(24),dp(24));message.setBackgroundColor(INK);setContentView(message);}}
    @Override public void onSaveInstanceState(Bundle out){out.putString("base",base);out.putInt("tab",tab.ordinal());JSONObject saved=new JSONObject();
        try{for(Map.Entry<String,UpgradePlanner.Filter> entry:filters.entrySet())saved.put(entry.getKey(),writeFilter(entry.getValue()));}catch(JSONException ignored){}
        out.putString("filters",saved.toString());super.onSaveInstanceState(out);}
    private static JSONObject writeFilter(UpgradePlanner.Filter f)throws JSONException{return new JSONObject().put("resources",new JSONArray(f.resources)).put("types",new JSONArray(f.types)).put("heroes",new JSONArray(f.heroes)).put("status",f.status).put("sort",f.sort.name()).put("hall",f.currentHallOnly);}
    private static UpgradePlanner.Filter readFilter(JSONObject json){UpgradePlanner.Filter f=new UpgradePlanner.Filter();String[] keys={"resources","types","heroes"};List<Set<String>> sets=Arrays.asList(f.resources,f.types,f.heroes);
        for(int i=0;i<keys.length;i++){JSONArray a=json.optJSONArray(keys[i]);if(a!=null)for(int n=0;n<a.length();n++)sets.get(i).add(a.optString(n));}
        f.status=json.optString("status","Remaining");f.currentHallOnly=json.optBoolean("hall",true);try{f.sort=UpgradePlanner.Sort.valueOf(json.optString("sort","DEFAULT"));}catch(Exception ignored){}return f;}
