        if(tab==UpgradePlanner.Tab.EQUIPMENT&&!r.item.hero.isEmpty()){LinearLayout owner=row();int id=heroId(r.item.hero);if(id>0){ImageView hero=new ImageView(this);hero.setImageResource(ItemArt.icon(this,id));owner.addView(hero,new LinearLayout.LayoutParams(dp(17),dp(20)));}owner.addView(label(r.item.hero,10,INK,true));names.addView(owner);}line.addView(names,new LinearLayout.LayoutParams(0,-2,1));LinearLayout quote=column();quote.setGravity(Gravity.END);quote.setPadding(dp(4),0,0,0);int width=getResources().getConfiguration().screenWidthDp<380?115:128;
