    private void addCost(LinearLayout parent,long amount,String currency){LinearLayout line=row();line.setGravity(Gravity.END);line.addView(label(String.format(Locale.US,"%,d",amount).replace(',',' '),15,WHITE,true));for(String name:currency.split(" or ")){int art=LevelArt.currency(this,name);if(art!=0){ImageView image=new ImageView(this);image.setImageResource(art);image.setContentDescription(name);image.setScaleType(ImageView.ScaleType.FIT_CENTER);line.addView(image,new LinearLayout.LayoutParams(dp(17),dp(19)));}else line.addView(label(" "+name,10,WHITE,false));}parent.addView(line);}
    private int heroId(String name){for(UpgradePlanner.Item item:planner.items())if(item.category.equals("hero")&&item.name.equals(name))return item.id;return 0;}
    private void details(UpgradePlanner.Row r){String text=r.status()+"\n\nCurrent level: "+r.level;if(r.next!=null)text+="\nNext level: "+r.targetLevel()+"\nBaseline cost: "+r.costText()+"\nBaseline duration: "+duration(r.seconds());text+="\n\nRequirements: "+(r.requirements.isEmpty()?"Check special conditions in game.":r.requirements)+"\nCurrent hall target: "+(r.hallCap>0?r.hallCap:"Unverified")+"\nCatalog max: "+r.item.max();if(r.count>1)text+="\n\nThis group contains "+r.count+" items at the same level. Costs and times are per item.";
        if(r.item.seasonal()||r.item.category.endsWith("hall")||r.item.data.optString("id").contains("multi-")||r.item.data.optString("id").contains("ricochet"))text+="\n\nMerge recipes, crafting, hall prerequisites and special unlock conditions require confirmation in game.";
        if(r.fresh&&r.item.tab==UpgradePlanner.Tab.ARMY)text+="\n\nThis army item was not included in the export. Its first catalog level is an unlock record, not a confirmed research job. Check its production-building and event conditions in game.";
        text+="\n\nArtwork previews the next level. Exported levels change after a fresh sync. Prices and future times are baseline catalog values before event or Gold Pass reductions. Running timers use exported boosts. Resource balances and equipped equipment are not supplied by this export; affordability and equipped status are not inferred.\n\nSuggested upgrades are up to three owned, requirement-met upgrades with the shortest baseline durations. These are local suggestions, independent of Supercell’s recommendations.\n\nCatalog checked 8 Nov 2026 · "+r.item.data.optString("source","No catalog entry");new AlertDialog.Builder(this).setTitle(r.item.name).setMessage(text).setPositiveButton("Close",null).setNeutralButton("Open Clash",(d,w)->startActivity(new Intent(this,MainActivity.class).setAction("com.villageclock.app.OPEN_GAME").putExtra("tag",village.tag))).show();}
